SELECT member_id, member_login_id, member_password, member_name, member_email, member_phone, member_birth, member_gender, created_at, updated_at
FROM member
WHERE member_id = #{memberId}

SELECT member_id, member_login_id, member_password, member_name, member_email, member_phone, member_birth, member_gender, created_at, updated_at
FROM member
WHERE member_login_id = #{memberLoginId}

SELECT member_id, member_login_id, member_password, member_name, member_email, member_phone, member_birth, member_gender, created_at, updated_at
FROM member
WHERE member_email = #{memberEmail}
